create table public.site_settings (id uuid primary key default gen_random_uuid(), site_name text not null default 'PES 2027 Revolution', beta_enabled boolean not null default false, presale_enabled boolean not null default false, sales_enabled boolean not null default false, hero_image_url text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.patch_versions (id uuid primary key default gen_random_uuid(), version text not null, channel text not null check(channel in ('beta','stable')), release_notes text, file_size_bytes bigint check(file_size_bytes >= 0), download_url text, published boolean not null default false, published_at timestamptz, created_at timestamptz not null default now());
create table public.patch_statistics (id uuid primary key default gen_random_uuid(), key text unique not null, label text not null, value bigint, suffix text, display_order integer not null default 0, visible boolean not null default true);
create table public.competitions (id uuid primary key default gen_random_uuid(), name text not null, slug text unique not null, country text, region text not null, category text, competition_type text not null, logo_url text, teams_count integer check(teams_count >= 0), availability_status text not null check(availability_status in ('beta','planned','final')), featured boolean not null default false, display_order integer not null default 0, created_at timestamptz not null default now());
create table public.contact_messages (id uuid primary key default gen_random_uuid(), name text not null, email text not null, subject text not null, message text not null check(char_length(message) between 12 and 1500), status text not null default 'new' check(status in ('new','read','resolved')), created_at timestamptz not null default now());
create table public.faq_items (id uuid primary key default gen_random_uuid(), question text not null, answer text not null, display_order integer not null default 0, visible boolean not null default true);
create table public.products (id uuid primary key default gen_random_uuid(), name text not null, slug text unique not null, description text, price_cents integer check(price_cents >= 0), currency text not null default 'BRL', active boolean not null default false, presale boolean not null default false, created_at timestamptz not null default now());
create index competitions_public_idx on public.competitions (featured, display_order); create index versions_published_idx on public.patch_versions (published, channel); create index contact_status_idx on public.contact_messages (status, created_at desc);
alter table public.site_settings enable row level security; alter table public.patch_versions enable row level security; alter table public.patch_statistics enable row level security; alter table public.competitions enable row level security; alter table public.contact_messages enable row level security; alter table public.faq_items enable row level security; alter table public.products enable row level security;
create policy "public reads published versions" on public.patch_versions for select using (published); create policy "public reads visible statistics" on public.patch_statistics for select using (visible); create policy "public reads competitions" on public.competitions for select using (true); create policy "public reads visible faq" on public.faq_items for select using (visible); create policy "public reads active products" on public.products for select using (active); create policy "public reads site settings" on public.site_settings for select using (true);
-- Contact submissions must use a protected Edge Function; no anonymous table policy is granted.
